using System.Text.RegularExpressions; using InovaGed.Environment.Doctor.Quality; namespace InovaGed.Environment.Doctor.Checks;
public sealed class AdministrationLinksQualityCheck:IQualityCheck {public string Name=>"Administração";public Task<IReadOnlyList<QualityFinding>> RunAsync(QualityContext c,CancellationToken ct){var file="InovaGed.Web/Controller/AdministrationController.cs";var source=File.ReadAllText(Path.Combine(c.Root,file));var cards=Regex.Matches(source, "new AdministrationActionVM\\([^\\n]+?\"([^\"]+)\",\\s*\"([^\"]+)\",\\s*AppPolicies\\.[^,]+,\\s*\"[^\"]+\",\\s*(true|false)");var r=new List<QualityFinding>();foreach(Match m in cards){var controller=m.Groups[1].Value;var action=m.Groups[2].Value;var available=m.Groups[3].Value=="true";var controllerPath=Directory.EnumerateFiles(Path.Combine(c.Root,"InovaGed.Web"),controller+"Controller.cs",SearchOption.AllDirectories).FirstOrDefault();var exists=controllerPath is not null&&Regex.IsMatch(File.ReadAllText(controllerPath),$@"\b{Regex.Escape(action)}\s*\(");var status=!available?QualityStatus.Warning:exists?QualityStatus.Pass:QualityStatus.Fail;r.Add(new(Name,status,$"Card {controller}/{action}: {(exists?"destino válido":available?"link quebrado":"indisponível")}",available&&!exists?"Navegação administrativa quebrada.":null,available&&!exists?"Criar/corrigir a action ou marcar o card indisponível.":null,Resource:file));}if(cards.Count==0)r.Add(new(Name,QualityStatus.Fail,"Nenhum card AdministrationActionVM foi localizado.","Catálogo administrativo não pôde ser validado."));return Task.FromResult<IReadOnlyList<QualityFinding>>(r);}}
